contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(afterBal == 0 && beforeBal >= 0 && cBalBefore - cBalAfter == beforeBal);
    }

    receive() external payable {}
    fallback() external payable {}
}

